import { useState, useMemo, useCallback, useEffect, useRef } from "react";
import { Product, filterProducts } from "@/data/store-data";
import { useSettings } from "@/context/SettingsContext";

interface UseCatalogueProps {
  initialProducts: Product[];
  initialFilters?: Record<string, string[]>;
}

export const useCatalogue = ({ initialProducts, initialFilters = {} }: UseCatalogueProps) => {
  // --- 1. STATE FOR FILTERING & SORTING ---
  const [activeFilters, setActiveFilters] = useState<Record<string, string[]>>(initialFilters);
  const [sortBy, setSortBy] = useState<string>("newest");

  // --- 2. AUTO-SCROLL ENGINE LOGIC ---
  const { settings } = useSettings();
  const [isAutoScrolling, setIsAutoScrolling] = useState(false);
  const scrollRef = useRef<number | null>(null);

  // Speed is derived from your global settings (autoScrollLevel)
  const currentScrollSpeed = useMemo(() => settings?.autoScrollLevel ?? 3, [settings?.autoScrollLevel]);

  const stopAutoScroll = useCallback(() => {
    setIsAutoScrolling(false);
    if (scrollRef.current) {
      cancelAnimationFrame(scrollRef.current);
      scrollRef.current = null;
    }
  }, []);

  const toggleAutoScroll = useCallback(() => {
    if (isAutoScrolling) {
      stopAutoScroll();
      return;
    }

    setIsAutoScrolling(true);

    const scrollStep = () => {
      window.scrollBy({ top: currentScrollSpeed, behavior: "auto" });

      const isAtBottom =
        window.innerHeight + window.scrollY >=
        document.documentElement.scrollHeight - 10;

      if (isAtBottom) {
        stopAutoScroll();
        return;
      }

      scrollRef.current = requestAnimationFrame(scrollStep);
    };

    scrollRef.current = requestAnimationFrame(scrollStep);
  }, [isAutoScrolling, currentScrollSpeed, stopAutoScroll]);

  // Emergency stop on manual user interaction
  useEffect(() => {
    const handleManualStop = () => {
      if (isAutoScrolling) stopAutoScroll();
    };

    window.addEventListener("wheel", handleManualStop, { passive: true });
    window.addEventListener("touchstart", handleManualStop, { passive: true });
    window.addEventListener("mousedown", handleManualStop, { passive: true });

    return () => {
      window.removeEventListener("wheel", handleManualStop);
      window.removeEventListener("touchstart", handleManualStop);
      window.removeEventListener("mousedown", handleManualStop);
    };
  }, [isAutoScrolling, stopAutoScroll]);

  // --- 3. THE ENGINE: FILTER AND SORT LOGIC ---
  const filteredAndSortedProducts = useMemo(() => {
    // Apply the universal filter engine from store-data
    let result = filterProducts(initialProducts, activeFilters);

    // Apply Sorting
    const sorted = [...result];
    switch (sortBy) {
      case "price-asc":
        sorted.sort((a, b) => a.defaultPrice - b.defaultPrice);
        break;
      case "price-desc":
        sorted.sort((a, b) => b.defaultPrice - a.defaultPrice);
        break;
      case "most-sold":
        sorted.sort((a, b) => b.salesCount - a.salesCount);
        break;
      case "popularity":
        sorted.sort((a, b) => b.popularityScore - a.popularityScore);
        break;
      default: // newest
        sorted.sort((a, b) => b.staticNumber - a.staticNumber);
    }
    return sorted;
  }, [initialProducts, activeFilters, sortBy]);

  // --- 4. HANDLERS ---
  const handleFilterChange = (key: string, value: string, isSingleSelect: boolean = false) => {
    setActiveFilters((prev) => {
      const currentValues = prev[key] || [];

      if (isSingleSelect) {
        return { ...prev, [key]: [value] };
      }

      const newValues = currentValues.includes(value)
        ? currentValues.filter((v) => v !== value)
        : [...currentValues, value];

      return { ...prev, [key]: newValues };
    });
  };

  const clearFilters = () => setActiveFilters({});

  return {
    products: filteredAndSortedProducts,
    activeFilters,
    handleFilterChange,
    clearFilters,
    sortBy,
    setSortBy,
    totalResults: filteredAndSortedProducts.length,
    // Scrolling Exports
    isAutoScrolling,
    toggleAutoScroll,
    stopAutoScroll,
  };
};